const body = $('Webhook Evolution (Mensaje Recibido)').first().json.body || {};
const data = body.data || {};
const key = data.key || {};

// 1. Descartar si el mensaje lo envió el propio bot (fromMe === true)
if (key.fromMe) {
  return [];
}

// 2. Descartar si es un grupo (@g.us) o estados/broadcast
const remoteJid = key.remoteJid || '';
if (!remoteJid.endsWith('@s.whatsapp.net')) {
  return [];
}

// 3. Extraer el número del remitente limpio
const senderNumber = remoteJid.replace('@s.whatsapp.net', '').replace(/[^0-9]/g, '');
if (!senderNumber || senderNumber.length < 9) {
  return [];
}

// 4. Redactar mensaje de autorespuesta educado y claro
const replyText = '¡Hola! 👋🌟\n\n' +
  'Este es un canal automático de avisos y recordatorios de *Centro Proyecta* y no podemos leer ni responder a los mensajes por aquí.\n\n' +
  'Si necesitas consultar o modificar tu cita, o hablar con el centro, por favor contáctanos directamente por WhatsApp en el teléfono de recepción pulsando aquí:\n' +
  '👉 https://wa.me/34684653227 (Recepción: 684 653 227)\n\n' +
  '¡Muchas gracias y disculpa las molestias! 😊✨';

return [{
  json: {
    sender_phone: senderNumber,
    reply_message: replyText
  }
}];

